-- 011_blokowane_formy_i_triggery.sql — Iteracja 15, karta I15.1 (ticket 107-FEATURE-products-blokady-triggery)
--
-- Backlog #73 (blokowane formy płatności per magazyn), #75/#79/#80/#82 (zamknięta lista zastosowań per
-- kategoria + kanoniczna kategoria). Decyzja D1 iteracji 15: przenosimy jako migrację odporną na to, że
-- na produkcji wszystko już istnieje.
--
-- ⭐ SKĄD TO SIĘ BIERZE. Produkcja NIE ma tego w żadnej migracji — zakłada to stary backend przy KAŻDYM
-- starcie procesu (`extensions.cjs` → `payment_blocks.cjs` `ensurePaymentBlocks()` i
-- `application_rules.cjs` `ensureApplicationRules()`, stan `origin/main` @ 7d6cfc9):
--   1. kolumna `products.blokowane_formy_platnosci TEXT` — `ALTER` tylko, gdy jej brak;
--   2. uzupełnienie CAŁEJ tabeli wartością z mapy dostawca → lista identyfikatorów form płatności;
--   3. `DROP TRIGGER IF EXISTS` + `CREATE TRIGGER` dla sześciu triggerów niżej.
-- Nowy stos nie ma takiego kodu startowego, więc bez tej migracji triggery zniknęłyby z bazy przy
-- pierwszej przebudowie tabeli, a na świeżej instalacji nie powstałyby wcale.
--
-- ⚠ IDEMPOTENCJA NA PRODUKCJI. Na produkcyjnej `data.db` kolumna i triggery JUŻ SĄ. Dlatego:
--   • kolumna — przez dyrektywę runnera (pierwsza linia po nagłówku; `db/migrate.ts`
--     `zastosujDyrektywy`): `PRAGMA table_info` → `ALTER` tylko przy braku. Gołe `ALTER` wywróciłoby
--     cały plik (`duplicate column name`), bo runner wykonuje go w jednej transakcji;
--   • uzupełnienie — `WHERE … IS NOT <wartość docelowa>`: na produkcji zmienia 0 wierszy;
--   • triggery — `DROP IF EXISTS` + `CREATE`, dokładnie jak produkcja przy starcie. Po migracji definicja
--     jest zawsze ta niżej, także gdyby baza miała starszą wersję triggera.
--
-- ⚠ TREŚĆ TRIGGERÓW JEST KOPIĄ BAJT W BAJT `git show 7d6cfc9:db/schema.sql` (linie 334–385) — to reguły
-- biznesowe Ani, nie upraszczać. Zostają też ASCII-only `UPPER()`/`LOWER()` (CLAUDE.md): np. kategoria
-- `LEŚNE` nie trafia w alias `leśne` i przechodzi jako `LEŚNE` — tak samo jak na produkcji.
-- MO6 celowo nie ma mapowania (CHANGELOG produkcji 2026-09-10: „MO6 Uniglory … nie będzie na razie
-- w sprzedaży”) → `NULL`, tak samo nieznany dostawca.
--
-- ⚠ CZEGO TU NIE MA (D2): kategorii i zastosowań ISTNIEJĄCYCH wierszy migracja nie normalizuje —
-- produkcja przy starcie też tego nie robi (`ensureApplicationRules()` wołane bez `backfill`), a
-- jednorazowe backfille z września (#79, #82) zostają poza migracjami. Triggery działają od teraz na
-- każdym INSERT i UPDATE kategorii/zastosowania/dostawcy.
--
-- Kolumna NIE wychodzi w API (`repos/kolumny.ts` `KOLUMNY_POZA_KONTRAKTEM`) — wystawia ją karta I15.3.

-- @dodaj-kolumne-jesli-brak products blokowane_formy_platnosci TEXT

-- Uzupełnienie istniejących wierszy — ten sam UPDATE co `ensurePaymentBlocks()` (CASE = treść triggera
-- `products_blokowane_formy_ai` z `NEW.dostawca` → `dostawca`).
UPDATE products
SET blokowane_formy_platnosci = CASE UPPER(TRIM(dostawca)) WHEN 'MO1' THEN '203, 204, 205, 206, 207, 208, 209, 210, 211, 212, 213, 214, 215, 216, 217, 218, 219' WHEN 'MO2' THEN '201, 202, 206, 207, 208, 209, 210, 211, 212, 213, 214, 215, 216, 217, 218, 219' WHEN 'MO3' THEN '201, 202, 203, 204, 205, 207, 208, 209, 210, 211, 212, 213, 214, 215, 216, 217, 218, 219' WHEN 'MO4' THEN '201, 202, 203, 204, 205, 206, 209, 210, 211, 212, 213, 214, 215, 216, 217, 218, 219' WHEN 'MO5' THEN '201, 202, 203, 204, 205, 206, 207, 208, 211, 212, 213, 214, 215, 216, 217, 218, 219' WHEN 'MO7' THEN '201, 202, 203, 204, 205, 206, 207, 208, 209, 210, 213, 214, 215, 216, 217, 218, 219' WHEN 'MO8' THEN '201, 202, 203, 204, 205, 206, 207, 208, 209, 210, 211, 212, 215, 216, 217, 218, 219' WHEN 'MO9' THEN '201, 202, 203, 204, 205, 206, 207, 208, 209, 210, 211, 212, 213, 214, 217, 218, 219' WHEN 'MO10' THEN '201, 202, 203, 204, 205, 206, 207, 208, 209, 210, 211, 212, 213, 214, 215, 216' ELSE NULL END
WHERE blokowane_formy_platnosci IS NOT CASE UPPER(TRIM(dostawca)) WHEN 'MO1' THEN '203, 204, 205, 206, 207, 208, 209, 210, 211, 212, 213, 214, 215, 216, 217, 218, 219' WHEN 'MO2' THEN '201, 202, 206, 207, 208, 209, 210, 211, 212, 213, 214, 215, 216, 217, 218, 219' WHEN 'MO3' THEN '201, 202, 203, 204, 205, 207, 208, 209, 210, 211, 212, 213, 214, 215, 216, 217, 218, 219' WHEN 'MO4' THEN '201, 202, 203, 204, 205, 206, 209, 210, 211, 212, 213, 214, 215, 216, 217, 218, 219' WHEN 'MO5' THEN '201, 202, 203, 204, 205, 206, 207, 208, 211, 212, 213, 214, 215, 216, 217, 218, 219' WHEN 'MO7' THEN '201, 202, 203, 204, 205, 206, 207, 208, 209, 210, 213, 214, 215, 216, 217, 218, 219' WHEN 'MO8' THEN '201, 202, 203, 204, 205, 206, 207, 208, 209, 210, 211, 212, 215, 216, 217, 218, 219' WHEN 'MO9' THEN '201, 202, 203, 204, 205, 206, 207, 208, 209, 210, 211, 212, 213, 214, 217, 218, 219' WHEN 'MO10' THEN '201, 202, 203, 204, 205, 206, 207, 208, 209, 210, 211, 212, 213, 214, 215, 216' ELSE NULL END;

DROP TRIGGER IF EXISTS products_blokowane_formy_ai;
DROP TRIGGER IF EXISTS products_blokowane_formy_au;
DROP TRIGGER IF EXISTS products_zastosowanie_ai;
DROP TRIGGER IF EXISTS products_zastosowanie_au;
DROP TRIGGER IF EXISTS manual_overrides_kategoria_ai;
DROP TRIGGER IF EXISTS manual_overrides_kategoria_au;

-- ——— Poniżej: dosłownie `git show 7d6cfc9:db/schema.sql`, linie 334–385 ———
CREATE TRIGGER products_blokowane_formy_ai
        AFTER INSERT ON products
        BEGIN
          UPDATE products
          SET blokowane_formy_platnosci = CASE UPPER(TRIM(NEW.dostawca)) WHEN 'MO1' THEN '203, 204, 205, 206, 207, 208, 209, 210, 211, 212, 213, 214, 215, 216, 217, 218, 219' WHEN 'MO2' THEN '201, 202, 206, 207, 208, 209, 210, 211, 212, 213, 214, 215, 216, 217, 218, 219' WHEN 'MO3' THEN '201, 202, 203, 204, 205, 207, 208, 209, 210, 211, 212, 213, 214, 215, 216, 217, 218, 219' WHEN 'MO4' THEN '201, 202, 203, 204, 205, 206, 209, 210, 211, 212, 213, 214, 215, 216, 217, 218, 219' WHEN 'MO5' THEN '201, 202, 203, 204, 205, 206, 207, 208, 211, 212, 213, 214, 215, 216, 217, 218, 219' WHEN 'MO7' THEN '201, 202, 203, 204, 205, 206, 207, 208, 209, 210, 213, 214, 215, 216, 217, 218, 219' WHEN 'MO8' THEN '201, 202, 203, 204, 205, 206, 207, 208, 209, 210, 211, 212, 215, 216, 217, 218, 219' WHEN 'MO9' THEN '201, 202, 203, 204, 205, 206, 207, 208, 209, 210, 211, 212, 213, 214, 217, 218, 219' WHEN 'MO10' THEN '201, 202, 203, 204, 205, 206, 207, 208, 209, 210, 211, 212, 213, 214, 215, 216' ELSE NULL END
          WHERE id = NEW.id;
        END;
CREATE TRIGGER products_blokowane_formy_au
